129	function ProtectedRoute({ children }: { children: React.ReactNode }) {
130	  return (
131	    <>
132	      <Show when="signed-in">{children}</Show>
133	      <Show when="signed-out">
134	        <Redirect to="/" />
135	      </Show>
136	    </>
137	  );
138	}
