140	function ClerkQueryClientCacheInvalidator() {
141	  const { addListener } = useClerk();
142	  const qc = useQueryClient();
143	  const prevUserIdRef = useRef<string | null | undefined>(undefined);
144	
145	  useEffect(() => {
146	    const unsubscribe = addListener(({ user }) => {
147	      const userId = user?.id ?? null;
148	      if (
149	        prevUserIdRef.current !== undefined &&
150	        prevUserIdRef.current !== userId
151	      ) {
152	        qc.clear();
153	      }
154	      prevUserIdRef.current = userId;
155	    });
156	    return unsubscribe;
157	  }, [addListener, qc]);
158	
159	  return null;
160	}
161	
162	function Routes() {
163	  return (
164	    <Switch>
165	      <Route path="/" component={HomeRedirect} />
166	      <Route path="/sign-in/*?" component={SignInPage} />
167	      <Route path="/sign-up/*?" component={SignUpPage} />
168	      <Route path="/feedback/:token" component={PublicFeedback} />
169	      <Route path="/join/:code" component={JoinWorkspace} />
170	      <Route path="/account">
171	        <ProtectedRoute>
172	          <Account />
173	        </ProtectedRoute>
174	      </Route>
175	      <Route path="/learn">
176	        <ProtectedRoute>
177	          <LearnPage />
178	        </ProtectedRoute>
179	      </Route>
180	      <Route path="/admin">
181	        <ProtectedRoute>
182	          <Admin />
183	        </ProtectedRoute>
184	      </Route>
185	      <Route path="/p/:projectId">
186	        {(params) => (
187	          <ProtectedRoute>
188	            <Workspace key={params.projectId} />
189	          </ProtectedRoute>
190	        )}
191	      </Route>
192	      <Route path="/:workspaceSlug/:projectSlug">
193	        {(params) =>
194	          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
195	            <NotFound />
196	          ) : (
197	            <ProtectedRoute>
198	              <WorkspaceBySlug key={`${params.workspaceSlug}/${params.projectSlug}`} />
199	            </ProtectedRoute>
200	          )
201	        }
202	      </Route>
203	      <Route path="/:workspaceSlug">
204	        {(params) =>
205	          RESERVED_TOP_PATHS.has(params.workspaceSlug) ? (
206	            <NotFound />
207	          ) : (
208	            <ProtectedRoute>
209	              <WorkspaceHome key={params.workspaceSlug} />
210	            </ProtectedRoute>
211	          )
212	        }
213	      </Route>
214	      <Route component={NotFound} />
215	    </Switch>
216	  );
217	}
218	
219	function ClerkProviderWithRoutes() {
220	  const [, setLocation] = useLocation();
221	  return (
222	    <ClerkProvider
223	      publishableKey={clerkPubKey}
224	      proxyUrl={clerkProxyUrl}
225	      appearance={clerkAppearance}
226	      signInUrl={`${basePath}/sign-in`}
227	      signUpUrl={`${basePath}/sign-up`}
228	      localization={{
229	        signIn: {
230	          start: { title: "Welcome back to GameForge", subtitle: "Sign in to continue designing your game" },
231	        },
232	        signUp: {
233	          start: { title: "Join GameForge", subtitle: "Build, simulate, and ship your board game" },
234	        },
235	      }}
236	      routerPush={(to) => setLocation(stripBase(to))}
237	      routerReplace={(to) => setLocation(stripBase(to), { replace: true })}
238	    >
239	      <QueryClientProvider client={queryClient}>
240	        <ClerkQueryClientCacheInvalidator />
241	        <TooltipProvider>
242	          <Routes />
243	          <Toaster />
244	        </TooltipProvider>
245	      </QueryClientProvider>
246	    </ClerkProvider>
247	  );
248	}
249	
250	function App() {
251	  return (
252	    <WouterRouter base={basePath}>
253	      <ClerkProviderWithRoutes />
254	    </WouterRouter>
255	  );
256	}
257	
258	export default App;
