141	  );
142	  const { data: project, isLoading: projectLoading } = useGetProject(projectId);
143	  const { data: stats } = useGetProjectStats(projectId);
144	  const deleteProject = useDeleteProject();
145	  const updateProject = useUpdateProject();
146	
147	  const [activeSection, setActiveSection] = useState<string>("overview");
